/**
 * Projects the rights record into the module the app imports.
 *
 * The track list and the credit list both come from `config/audio-rights-evidence.v1.json`,
 * which is what makes the attribution obligation un-forgettable: a CC-BY track cannot reach
 * the game without its credit line arriving in the same generated file. Nobody has to
 * remember to update a credits screen, because nobody can add music without updating it.
 *
 * Run: node tools/audio/write-licensed-music.mjs [--check]
 */

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const evidencePath = resolve(root, 'config/audio-rights-evidence.v1.json');
const outputPath = resolve(root, 'apps/mobile/src/features/feedback/licensed-music.generated.ts');

export function buildLicensedMusicModule() {
  const evidence = JSON.parse(readFileSync(evidencePath, 'utf8'));
  const accepted = new Map(evidence.acceptedLicences.map((entry) => [entry.id, entry]));
  const tracks = evidence.licensed.map((entry) => ({ file: entry.file, mood: entry.mood, gain: entry.gain }));
  const credits = evidence.licensed
    .filter((entry) => accepted.get(entry.licence)?.attributionRequired === true)
    .map((entry) => entry.attribution)
    .sort((left, right) => left.localeCompare(right));

  const trackLines = tracks
    .map((track) => `  { file: '${track.file}', mood: '${track.mood}', gain: ${track.gain} },`)
    .join('\n');
  const creditLines = credits.map((credit) => `  ${JSON.stringify(credit)},`).join('\n');

  return `/**
 * Generated by \`pnpm audio:music\` from config/audio-rights-evidence.v1.json. Do not edit.
 *
 * Both lists come from the rights record, which is what makes the credit obligation
 * un-forgettable: a CC-BY track cannot be added to the game without its line landing here.
 */

import type { MusicTrack } from './music-model';

export const LICENSED_TRACKS: readonly MusicTrack[] = [
${trackLines}
];

/** Shown on the credits screen. Empty only when nothing licensed needs attribution. */
export const AUDIO_CREDITS: readonly string[] = [
${creditLines}
];
`;
}

function main() {
  const expected = buildLicensedMusicModule();
  if (process.argv.includes('--check')) {
    const actual = existsSync(outputPath) ? readFileSync(outputPath, 'utf8') : '';
    if (actual !== expected) {
      process.stderr.write('licensed-music.generated.ts is stale; run pnpm audio:music\n');
      process.exitCode = 1;
      return;
    }
    process.stdout.write('licensed music projection is current\n');
    return;
  }
  writeFileSync(outputPath, expected, 'utf8');
  process.stdout.write(`wrote ${outputPath}\n`);
}

if (process.argv[1] !== undefined && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main();
}
